import { useEffect } from "react";

const FONT = "16px Test Sans";
const LINE_HEIGHT = 19;

export function PretextTest() {
  useEffect(() => {
    const prepared = prepareWithSegments(
      "生活就像海洋\u200B 只有意志坚定的人才能到达彼岸",
      FONT,
    );
    const width = prepared.widths[0]! - 1;

    console.log(
      layoutWithLines(prepared, width, LINE_HEIGHT).lines.map(
        (line) => line.text,
      ),
    );

    console.log(collect(prepared, width));
  }, []);
  return <div>Pretext Test</div>;
}

function collect(prepared, width) {
  const out = [];
  let cursor = { segmentIndex: 0, graphemeIndex: 0 };
  while (true) {
    const line = layoutNextLine(prepared, cursor, width);
    if (line === null) break;
    out.push(line.text);
    cursor = line.end;
  }
  return out;
}
